<script setup>
import {computed,ref} from 'vue'

import HelpTip from '../shared/components/HelpTip.vue'
import {toast} from '../shared/composables/toast.js'
const props=defineProps({modelValue:{type:Array,default:()=>[]},disabled:Boolean,readonly:Boolean})
const emit=defineEmits(['update:modelValue'])
const cells={},names={},addButton=ref(null)
const open=ref(false),column=ref(''),type=ref('string')
const columns=computed(()=>[...new Set(props.modelValue.flatMap(row=>Object.keys(row.values||{})))])
const types=[{value:'string',label:'文本'},{value:'number',label:'数字'},{value:'boolean',label:'布尔值'},{value:'null',label:'空值 null'}]
const reference=key=>'{{data.'+key+'}}'
function addRow(){emit('update:modelValue',[...props.modelValue,{name:'数据组 '+(props.modelValue.length+1),values:Object.fromEntries(columns.value.map(k=>[k,{type:props.modelValue[0]?.values[k]?.type||'string',value:props.modelValue[0]?.values[k]?.type==='boolean'?'true':''}]))}])}
function addColumn(){const key=column.value.trim();if(!/^[A-Za-z_][A-Za-z0-9_]{0,63}$/.test(key)||columns.value.includes(key)){toast('列名使用不重复的英文字母、数字和下划线，且不能以数字开头','warning');return false}const rows=props.modelValue.length?props.modelValue:[{name:'数据组 1',values:{}}];emit('update:modelValue',rows.map(row=>({...row,values:{...row.values,[key]:{type:type.value,value:type.value==='boolean'?'true':''}}})));open.value=false;return true}
function removeColumn(key){emit('update:modelValue',props.modelValue.map(row=>({...row,values:Object.fromEntries(Object.entries(row.values).filter(([k])=>k!==key))})))}
function focus(){const seen=new Set();for(let i=0;i<props.modelValue.length;i++){const row=props.modelValue[i];if(!row.name?.trim()||seen.has(row.name)){focusControl(names[i]);return}seen.add(row.name);for(const [key,cell] of Object.entries(row.values||{})){if((cell.type==='number'&&!/^-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?$/.test(cell.value))||(cell.type==='boolean'&&!['true','false'].includes(cell.value))){focusControl(cells[i+':'+key]);return}}}const target=Object.values(cells)[0]||names[0];if(target)focusControl(target);else focusControl(addButton.value?.$el)}
defineExpose({focus})

import OptionPicker from '../shared/components/OptionPicker.vue'

import {copyText} from '../shared/clipboard.js'

import {focusControl} from '../shared/focusControl.js'


import {Button,Dialog,DialogContent,DialogDescription,DialogFooter,DialogHeader,DialogTitle,Empty,EmptyDescription,EmptyHeader,Field,FieldDescription,FieldError,FieldLabel,Input,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../shared/shadcn-ui.js'
</script>
<template><div v-if="!readonly" class="data-actions"><Button ref="addButton" @click="addRow" variant="outline" size="default" type="button" :disabled="(disabled||modelValue.length>=20)">添加数据组</Button><Button @click="column='';type='string';open=true" variant="outline" size="default" type="button" :disabled="(disabled||columns.length>=20)">添加数据列</Button><HelpTip text="不配置数据时执行一次；配置后每组数据分别执行整个用例。复制列名下方的引用到请求或断言，例如 {{data.order_id}}。每组数据独立传递步骤变量；任一组合未通过即停止后续组合。最多 20 组，每组 20 列。"/></div><div class="min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:Math.max(600,columns.length*220+250)}).y?({x:Math.max(600,columns.length*220+250)}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:Math.max(600,columns.length*220+250)}).x||({x:Math.max(600,columns.length*220+250)}).minWidth||480)+'px'}"><TableHeader><TableRow><TableHead :class="(&quot;left&quot;)==='right'?'sticky right-0 z-10 bg-background':(&quot;left&quot;)==='left'?'sticky left-0 z-10 bg-background':''" :style="{width:(180)+'px'}">数据组</TableHead><TableHead v-for="key in columns" :key="key" :style="{width:(220)+'px'}"><div>{{key}}<Button v-if="!readonly" @click="removeColumn(key)" class="text-destructive" :variant="'destructive'" size="xs" type="button" :disabled="(disabled)">移除</Button></div><span class="min-w-0 break-words"><code>{{reference(key)}}</code><Button variant="ghost" size="xs" aria-label="复制内容" @click="copyText(Array.from($event.currentTarget.parentElement.childNodes).filter(node=>node!==$event.currentTarget).map(node=>node.textContent).join(''))">复制</Button></span></TableHead><TableHead v-if="!readonly" :class="(&quot;right&quot;)==='right'?'sticky right-0 z-10 bg-background':(&quot;right&quot;)==='left'?'sticky left-0 z-10 bg-background':''" :style="{width:(80)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (modelValue||[])" :key="typeof ('id')==='function'?('id')(record):record['id']??rowIndex"><TableRow><TableCell class="align-top" :class="(&quot;left&quot;)==='right'?'sticky right-0 z-10 bg-background':(&quot;left&quot;)==='left'?'sticky left-0 z-10 bg-background':''"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record,rowIndex} in [{record,rowIndex}]"><span v-if="readonly">{{record.name}}</span><Input v-else :ref="el=>names[rowIndex]=el" v-model="record.name" :disabled="disabled" aria-label="数据组名称"/></template></div></TableCell><TableCell v-for="key in columns" :key="key" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record,rowIndex} in [{record,rowIndex}]"><span v-if="readonly" class="min-w-0 break-words"><code>{{record.values[key]?.type==='null'?'null':record.values[key]?.value===''?'（空文本）':record.values[key]?.value}}</code></span><Input v-else-if="record.values[key]?.type==='null'" model-value="null" disabled/><OptionPicker :ref="el=>cells[rowIndex+':'+key]=el" v-else-if="record.values[key]?.type==='boolean'" v-model="record.values[key].value" :disabled="disabled" :aria-label="record.name+' '+key" class="min-w-36" :options="['true','false']"/><Input :ref="el=>cells[rowIndex+':'+key]=el" v-else-if="record.values[key]" v-model="record.values[key].value" :disabled="disabled" :placeholder="record.values[key].type==='number'?'数字，保留完整精度':'文本，可留空'" :aria-label="record.name+' '+key"/></template></div></TableCell><TableCell v-if="!readonly" class="align-top" :class="(&quot;right&quot;)==='right'?'sticky right-0 z-10 bg-background':(&quot;right&quot;)==='left'?'sticky left-0 z-10 bg-background':''"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{rowIndex} in [{record,rowIndex}]"><Button @click="emit('update:modelValue',modelValue.filter((_,i)=>i!==rowIndex))" variant="ghost" size="default" type="button" :disabled="(disabled)">移除</Button></template></div></TableCell></TableRow></template><TableRow v-if="!(modelValue||[]).length"><TableCell :colspan="3">未配置数据组，使用步骤中填写的参数执行一次</TableCell></TableRow></TableBody></Table></div></div><Dialog :open="open" @update:open="async v=>{if(!v){open=false;}}"><DialogContent class="flex max-h-[92dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof ('min(960px,94vw)')==='number'?('min(960px,94vw)')+'px':('min(960px,94vw)')}" :show-close-button="true" @interact-outside="e=>{e.preventDefault()}"><DialogHeader class="shrink-0 border-b p-5 pr-12"><DialogTitle>添加数据列</DialogTitle><DialogDescription class="sr-only">详情与操作</DialogDescription></DialogHeader><div class="min-h-0 flex-1 overflow-auto p-5"><fieldset class="min-w-0 space-y-5" ><Field><FieldLabel>列名 <span class="text-destructive">*</span></FieldLabel><Input v-model="column" placeholder="例如 order_id" aria-label="数据列名" :maxlength="64"/></Field><Field><FieldLabel>数据类型</FieldLabel><OptionPicker v-model="type" aria-label="数据列类型" class="min-w-36" :options="types"/></Field></fieldset></div><DialogFooter class="shrink-0 flex-wrap border-t p-4"><Button variant="outline" @click="async()=>{open=false;}">取消</Button><Button @click="async()=>{if(await (addColumn)()!==false){open=false;}}">确认</Button></DialogFooter></DialogContent></Dialog></template>
<style scoped>.data-actions{display:flex;gap:12px;align-items:center;margin-bottom:16px;flex-wrap:wrap}</style>
